\section{Introduction}

\subsection{The problem}
Expand
\[
(p+q)^n=\sum_{k=0}^n\binom nk p^kq^{\,n-k},\qquad p,q>0,
\]
and ask which summand is largest. The usual answer is ``about $np/(p+q)$'', with an occasional parenthetical that two adjacent terms can tie. Exactly which index maximises, and exactly when the maximiser fails to be unique, is normally treated only in the symmetric case $p=q=1$.

The structural reason a complete answer is available is that the binomial weights are \emph{strictly log-concave}, and strict log-concavity is precisely the hypothesis limiting ties to pairs. We develop the theory in three layers: an abstract layer (strictly log-concave windows and the comparison of the two bracketing degrees), a mechanism layer (threshold windows, making both degrees explicit roundings of one real parameter), and an instance layer (binomial and Poisson weights, arithmetic tie criteria, parameter dependence, cross-instance comparison).

\subsection{Notation}
Sequences are indexed by $k\in\{0,\dots,n\}$, the \emph{window}. For $x\ge0$, $\lfloor x\rfloor$ and $\lceil x\rceil$ are the non-negative floor and ceiling. Every threshold below is strictly positive, so $\lceil\theta\rceil\ge1$ and $\lceil\theta\rceil-1$ is a non-negative integer.

\section{Strictly log-concave windows}

\begin{definition}[Strictly log-concave window]
A sequence $a:\N\to\mathbb{R}$ is \emph{strictly log-concave on the window} $\{0,\dots,n\}$ if $a_k>0$ for all $k\le n$ and
\[
a_k\,a_{k+2}<a_{k+1}^2\qquad\text{for all }k\text{ with }k+2\le n.
\]
\end{definition}

Equivalently, the points $(k,\log a_k)$ lie in strictly concave position: each interior point lies strictly above the chord joining its neighbours.

\begin{lemma}[Ratio decrease]\label{lem:ratio}
If $a$ is strictly log-concave on $\{0,\dots,n\}$ and $k+2\le n$, then $a_{k+2}/a_{k+1}<a_{k+1}/a_k$.
\end{lemma}

\begin{proof}
Both denominators are positive; cross-multiplying, the claim is the strict Newton inequality.
\end{proof}

\begin{lemma}[Strict antitonicity of ratios]\label{lem:anti}
If $j<k<n$ then $a_{k+1}/a_k<a_{j+1}/a_j$.
\end{lemma}

\begin{proof}
Induction on $k$ from $k=j+1$, using Lemma \ref{lem:ratio} and transitivity.
\end{proof}

\begin{lemma}[Rise propagates backwards]\label{lem:back}
If $j<k<n$ and $a_k\le a_{k+1}$, then $a_j<a_{j+1}$.
\end{lemma}

\begin{proof}
The hypothesis says $a_{k+1}/a_k\ge1$; Lemma \ref{lem:anti} gives $a_{j+1}/a_j>1$.
\end{proof}

\begin{lemma}[Fall propagates forwards]\label{lem:fwd}
If $j<k<n$ and $a_{j+1}\le a_j$, then $a_{k+1}<a_k$.
\end{lemma}

\begin{proof}
Here $a_{j+1}/a_j\le1$, so $a_{k+1}/a_k<1$ by Lemma \ref{lem:anti}.
\end{proof}

\begin{definition}[The two bracketing degrees]
\[
\dminus:=\min\{k\le n:\ k=n\ \text{or}\ a_{k+1}\le a_k\},\qquad
\dplus:=\min\{k\le n:\ k=n\ \text{or}\ a_{k+1}<a_k\}.
\]
\end{definition}

Both minima are over non-empty sets ($k=n$ always qualifies), so $\dminus,\dplus\le n$. Minimality gives: $a_j<a_{j+1}$ for $j<\dminus$; $a_j\le a_{j+1}$ for $j<\dplus$; $a_{\dminus+1}\le a_{\dminus}$ if $\dminus<n$; and $a_{\dplus+1}<a_{\dplus}$ if $\dplus<n$.

\begin{lemma}\label{lem:order}
$\dminus\le\dplus$ for any positive sequence (log-concavity is not needed).
\end{lemma}

\begin{proof}
If $\dplus<\dminus\le n$ then $\dplus<n$, so $a_{\dplus+1}<a_{\dplus}$; but $\dplus<\dminus$ gives $a_{\dplus}<a_{\dplus+1}$.
\end{proof}

\begin{lemma}[Characterisation]\label{lem:char}
Let $d\le n$. If $(d=n$ or $a_{d+1}\le a_d)$ and $a_j<a_{j+1}$ for all $j<d$, then $\dminus=d$. If $(d=n$ or $a_{d+1}<a_d)$ and $a_j\le a_{j+1}$ for all $j<d$, then $\dplus=d$.
\end{lemma}

\begin{proof}
Immediate from minimality of the defining sets.
\end{proof}

\begin{theorem}[Comparison of the bracketing degrees]\label{thm:compare}
Let $a$ be strictly log-concave on $\{0,\dots,n\}$. Then
\begin{enumerate}
\item $\dplus\le\dminus+1$;
\item $\dplus=\dminus+1\iff(\dminus<n$ and $a_{\dminus}=a_{\dminus+1})$;
\item $\dplus-\dminus\in\{0,1\}$, and $\dminus=\dplus$ exactly when there is no tie at the top.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) Suppose $\dplus>\dminus+1$ and write $d=\dminus$, so $d+1<\dplus\le n$. Since $d<\dplus$ and $d+1<\dplus$, no fall occurs at $d$ or $d+1$: $a_d\le a_{d+1}$ and $a_{d+1}\le a_{d+2}$. Since $d<n$, the definition of $\dminus$ gives $a_{d+1}\le a_d$, hence $a_d=a_{d+1}$. Then
\[
a_d\,a_{d+2}\ \ge\ a_d\,a_{d+1}\ =\ a_{d+1}^2,
\]
contradicting the strict Newton inequality at $d$ (valid since $d+2\le n$).

(2) ($\Rightarrow$) $\dplus=\dminus+1\le n$ gives $\dminus<n$, hence $a_{\dminus+1}\le a_{\dminus}$; and $\dminus<\dplus$ gives $a_{\dminus}\le a_{\dminus+1}$. ($\Leftarrow$) A strict fall at $\dminus$ is excluded by the equality, so $\dplus\neq\dminus$; with $\dminus\le\dplus\le\dminus+1$ this forces $\dplus=\dminus+1$.

(3) Combine (1), (2) and Lemma \ref{lem:order}.
\end{proof}

Strict log-concavity is used exactly once, in part (1), and for exactly one purpose: to exclude a plateau of length three.

\begin{proposition}[Strict increase below]\label{prop:below}
If $j<k\le\dminus$ then $a_j<a_k$.
\end{proposition}

\begin{proof}
Induction on $k$, each step a strict rise below $\dminus$.
\end{proof}

\begin{proposition}[Strict decrease above]\label{prop:above}
Let $a$ be strictly log-concave. If $\dplus\le j<k\le n$ then $a_k<a_j$.
\end{proposition}

\begin{proof}
One step first: for $\dplus\le j<n$, if $j=\dplus$ this is the definition; if $j>\dplus$ then $\dplus<n$, so $a_{\dplus+1}<a_{\dplus}$ and Lemma \ref{lem:fwd} applied to the pair $(\dplus,j)$ gives $a_{j+1}<a_j$. Induct on $k$.
\end{proof}

\begin{proposition}\label{prop:peakval}
$a_{\dminus}=a_{\dplus}$.
\end{proposition}

\begin{proof}
If $\dminus=\dplus$ this is trivial; otherwise $\dplus=\dminus+1$ and Theorem \ref{thm:compare}(2) applies.
\end{proof}

\begin{theorem}[Strict unimodality; maximiser set]\label{thm:unimodal}
Let $a$ be strictly log-concave on $\{0,\dots,n\}$ and $k\le n$. Then $a_k\le a_{\dminus}$, with strict inequality when $k<\dminus$ or $k>\dplus$; consequently
\[
a_k=\max_{0\le j\le n}a_j\iff \dminus\le k\le\dplus .
\]
\end{theorem}

\begin{proof}
For $k<\dminus$ use Proposition \ref{prop:below}; for $k>\dplus$ use Propositions \ref{prop:above} and \ref{prop:peakval}. Otherwise $\dminus\le k\le\dplus\le\dminus+1$ forces $k\in\{\dminus,\dplus\}$ and $a_k=a_{\dminus}$.
\end{proof}

\section{Threshold windows}

\begin{definition}[Threshold window]
A sequence $a$ is a \emph{threshold window on $\{0,\dots,n\}$ with threshold $\theta$} if $0<\theta<n+1$ and, for all $k<n$,
\[
a_k<a_{k+1}\iff k+1<\theta,\qquad\qquad a_k\le a_{k+1}\iff k+1\le\theta .
\]
\end{definition}

The two criteria are the same computation with $<$ and with $\le$; the whole tie phenomenon lives in their difference.

\begin{lemma}\label{lem:round}
For $\theta\ge0$, $\lfloor\theta\rfloor=\lceil\theta\rceil\iff\theta\in\Z$.
\end{lemma}

\begin{proof}
If the roundings agree then $\lfloor\theta\rfloor\le\theta\le\lceil\theta\rceil=\lfloor\theta\rfloor$; conversely both fix integers.
\end{proof}

\begin{theorem}[Explicit brackets]\label{thm:explicit}
For a threshold window with threshold $\theta$,
\[
\dminus=\lceil\theta\rceil-1,\qquad \dplus=\lfloor\theta\rfloor .
\]
\end{theorem}

\begin{proof}
\emph{Lower bracket.} Put $d=\lceil\theta\rceil-1$; from $0<\theta<n+1$ we get $1\le\lceil\theta\rceil\le n+1$, so $0\le d\le n$. For $j<d$ we have $j+1<\lceil\theta\rceil$, hence $j+1<\theta$ (otherwise $\lceil\theta\rceil\le j+1$), so the strict criterion gives $a_j<a_{j+1}$. At $d$: if $d=n$ we are done; otherwise $d+1=\lceil\theta\rceil\ge\theta$, so the strict criterion fails and $a_{d+1}\le a_d$. Apply Lemma \ref{lem:char}.

\emph{Upper bracket.} Put $d=\lfloor\theta\rfloor\le n$. For $j<d$ we have $j+1\le\lfloor\theta\rfloor\le\theta$, so the weak criterion gives $a_j\le a_{j+1}$. At $d$: if $d=n$ we are done; otherwise $d+1>\theta$, so the weak criterion fails and $a_{d+1}<a_d$. Apply Lemma \ref{lem:char}.
\end{proof}

\begin{theorem}[Explicit comparison]\label{thm:gap}
For a threshold window with threshold $\theta$,
\[
\dplus=\dminus+1\iff\theta\in\Z .
\]
When $\theta\notin\Z$ the maximiser is unique and equals $\lfloor\theta\rfloor$.
\end{theorem}

\begin{proof}
By Theorem \ref{thm:explicit} the identity $\dplus=\dminus+1$ reads $\lfloor\theta\rfloor=\lceil\theta\rceil$, which is Lemma \ref{lem:round}. If $\theta\notin\Z$ then $\lfloor\theta\rfloor\neq\lceil\theta\rceil\le\lfloor\theta\rfloor+1$, forcing $\lceil\theta\rceil-1=\lfloor\theta\rfloor$.
\end{proof}

\begin{theorem}[Monotonicity in the threshold]\label{thm:mono}
If $a$ is a threshold window on $\{0,\dots,n\}$ with threshold $\theta$ and $a'$ one on $\{0,\dots,n'\}$ with threshold $\theta'\ge\theta$, then $\dminus(a)\le\dminus(a')$ and $\dplus(a)\le\dplus(a')$.
\end{theorem}

\begin{proof}
Floor and ceiling are monotone.
\end{proof}

\begin{theorem}[Unit staircase]\label{thm:step}
Under the same hypotheses, if $\theta'<\theta+1$ then $\dminus(a')\le\dminus(a)+1$ and $\dplus(a')\le\dplus(a)+1$.
\end{theorem}

\begin{proof}
$\theta'<\theta+1\le\lceil\theta\rceil+1$ gives $\lceil\theta'\rceil\le\lceil\theta\rceil+1$; $\theta'<\lfloor\theta\rfloor+2$ gives $\lfloor\theta'\rfloor\le\lfloor\theta\rfloor+1$.
\end{proof}

\section{The binomial instance}

\begin{theorem}[Strict log-concavity of a Pascal row]\label{thm:pascal}
For $k+2\le n$,
\[
\binom nk\binom n{k+2}<\binom n{k+1}^2 .
\]
\end{theorem}

\begin{proof}
Write $n=k+2+m$, $m\ge0$. The absorption identity $\binom n{j+1}(j+1)=\binom nj(n-j)$ gives
\[
\binom n{k+1}(k+1)=\binom nk(m+2),\qquad \binom n{k+2}(k+2)=\binom n{k+1}(m+1).
\]
Multiplying and rearranging,
\[
\binom n{k+1}^2(k+1)(m+1)=\binom nk\binom n{k+2}(m+2)(k+2).
\]
All coefficients are positive. If $\binom nk\binom n{k+2}\ge\binom n{k+1}^2$ then, since $(m+2)(k+2)>(m+1)(k+1)$, the right-hand side would strictly exceed the left, a contradiction.
\end{proof}

\begin{definition}[Binomial weights and mode parameter]
For $p,q>0$ set $w_k:=\binom nk p^kq^{\,n-k}$ for $0\le k\le n$, so $\sum_k w_k=(p+q)^n$, and
\[
\theta=\theta(n,p,q):=\frac{(n+1)p}{p+q}.
\]
\end{definition}

\begin{lemma}\label{lem:thetarange}
For $p,q>0$: $w_k>0$ for $k\le n$, and $0<\theta<n+1$.
\end{lemma}

\begin{proof}
Positivity is clear; $\theta<n+1$ is $(n+1)p<(n+1)(p+q)$.
\end{proof}

\begin{theorem}\label{thm:binlc}
The binomial weights are strictly log-concave on $\{0,\dots,n\}$.
\end{theorem}

\begin{proof}
For $k+2\le n$ write $n=k+2+m$. Then $w_kw_{k+2}=\binom nk\binom n{k+2}p^{2k+2}q^{2m+2}$ and $w_{k+1}^2=\binom n{k+1}^2p^{2k+2}q^{2m+2}$; apply Theorem \ref{thm:pascal} and multiply by $p^{2k+2}q^{2m+2}>0$.
\end{proof}

\begin{theorem}[Rise criterion]\label{thm:binrise}
For $k<n$,
\[
w_k<w_{k+1}\iff k+1<\theta,\qquad w_k\le w_{k+1}\iff k+1\le\theta .
\]
\end{theorem}

\begin{proof}
Write $n=k+1+m$ and factor out $p^kq^m>0$:
\[
w_k=\Big(\binom nk q\Big)p^kq^m,\qquad w_{k+1}=\Big(\binom n{k+1}p\Big)p^kq^m,
\]
so the comparison of $w_k,w_{k+1}$ is that of $\binom nk q$ and $\binom n{k+1}p$. Multiplying by $k+1>0$ and using $\binom n{k+1}(k+1)=\binom nk(m+1)$, then cancelling $\binom nk>0$, the comparison becomes that of $q(k+1)$ and $(m+1)p=(n-k)p$, i.e. of $(k+1)(p+q)$ and $(n+1)p$, i.e. of $k+1$ and $\theta$. The chain is valid verbatim with $\le$ in place of $<$.
\end{proof}

\begin{corollary}\label{cor:binthresh}
For $p,q>0$ the binomial weights form a threshold window on $\{0,\dots,n\}$ with threshold $\theta=(n+1)p/(p+q)$.
\end{corollary}

\begin{theorem}[Explicit binomial brackets]\label{thm:binbrack}
For $p,q>0$,
\[
\dminus=\left\lceil\frac{(n+1)p}{p+q}\right\rceil-1,\qquad \dplus=\left\lfloor\frac{(n+1)p}{p+q}\right\rfloor,
\]
the maximiser set of $(w_k)_{k\le n}$ is exactly $\{k:\dminus\le k\le\dplus\}$, and $\dplus=\dminus+1$ if and only if $\theta\in\Z$; otherwise the maximiser is unique and equals $\lfloor\theta\rfloor$.
\end{theorem}

\begin{proof}
Combine Corollary \ref{cor:binthresh} with Theorems \ref{thm:explicit}, \ref{thm:gap} and, for the maximiser set, Theorems \ref{thm:binlc} and \ref{thm:unimodal}.
\end{proof}

\begin{theorem}[Integer weights]\label{thm:intweights}
For positive integers $P,Q$ and $p=P$, $q=Q$,
\[
\dplus=\dminus+1\iff (P+Q)\mid (n+1)P .
\]
\end{theorem}

\begin{proof}
By Theorem \ref{thm:binbrack} the left side is integrality of $\theta=(n+1)P/(P+Q)$. If $\theta=m\in\N$ then $(n+1)P=m(P+Q)$; conversely $(n+1)P=(P+Q)c$ gives $\theta=c$.
\end{proof}

\begin{theorem}[The classical row]\label{thm:classical}
For $p=q=1$ one has $w_k=\binom nk$, $\theta=(n+1)/2$,
\[
\dminus=\left\lfloor\frac n2\right\rfloor,\qquad \dplus=\left\lfloor\frac{n+1}2\right\rfloor=\left\lceil\frac n2\right\rceil,
\]
and the row has a two-term plateau at the top if and only if $n$ is odd.
\end{theorem}

\begin{proof}
If $n=2t$ then $\theta=t+\tfrac12$, so $\lceil\theta\rceil-1=t=\lfloor\theta\rfloor$ and the maximiser $\binom{2t}t$ is unique. If $n=2t+1$ then $\theta=t+1\in\Z$, so $\lceil\theta\rceil-1=t$, $\lfloor\theta\rfloor=t+1$, and $\binom{2t+1}t=\binom{2t+1}{t+1}$. In both cases the stated formulas hold, and by Theorem \ref{thm:gap} the gap is $1$ exactly when $\theta\in\Z$, i.e. exactly for odd $n$.
\end{proof}

\begin{theorem}[Two-sided bracket for the peak value]\label{thm:peakbracket}
For $p,q>0$,
\[
\frac{(p+q)^n}{n+1}\ \le\ w_{\dminus}\ \le\ (p+q)^n .
\]
\end{theorem}

\begin{proof}
$\sum_{k=0}^n w_k=(p+q)^n$ with all terms positive gives the upper bound. All terms are $\le w_{\dminus}$ by Theorem \ref{thm:binbrack}, so $(p+q)^n\le(n+1)w_{\dminus}$.
\end{proof}

\begin{lemma}\label{lem:monop}
For fixed $q>0$, $\theta(n,p,q)$ is non-decreasing in $p$; and $\theta(n+1,p,q)=\theta(n,p,q)+\frac p{p+q}$ with $0<\frac p{p+q}<1$.
\end{lemma}

\begin{proof}
$p\mapsto p/(p+q)=1-q/(p+q)$ is increasing for $p>0$; the second identity is a direct computation.
\end{proof}

\begin{theorem}[Monotone mode; unit staircase]\label{thm:paramdep}
Let $q>0$. If $0<p_1\le p_2$ then both bracketing degrees for $p_1$ are at most the corresponding degrees for $p_2$. Moreover, for fixed $p,q>0$,
\[
\dplus(n)\ \le\ \dplus(n+1)\ \le\ \dplus(n)+1 .
\]
\end{theorem}

\begin{proof}
Combine Lemma \ref{lem:monop} with Theorems \ref{thm:mono} and \ref{thm:step}.
\end{proof}

\begin{theorem}[Vertex sweep]\label{thm:vertex}
Let $d\le n$. With $q=1$ and
\[
\theta=d+\tfrac12,\qquad p=\frac{\theta}{n+1-\theta}=\frac{2d+1}{2n-2d+1}>0,
\]
the degree $d$ is the \emph{unique} maximiser of $k\mapsto\binom nk p^k$ on $\{0,\dots,n\}$.
\end{theorem}

\begin{proof}
Solving $(n+1)p/(p+1)=\theta$ for $\theta\in(0,n+1)$ gives $p=\theta/(n+1-\theta)>0$. For $\theta=d+\tfrac12$, $\lceil\theta\rceil-1=d=\lfloor\theta\rfloor$, so both brackets equal $d$ by Theorem \ref{thm:binbrack}; strictness for $k\neq d$ is Theorem \ref{thm:unimodal}.
\end{proof}

Thus all $n+1$ points $(k,\log\binom nk)$ are vertices of their upper convex hull: as $\theta$ sweeps $(0,n+1)$, the argmax sweeps every degree in turn, tying exactly at the integers.

\section{The Poisson instance and a cross-instance comparison}

\begin{definition}
For $\lambda>0$ set $u_k:=\lambda^k/k!$.
\end{definition}

\begin{theorem}\label{thm:poislc}
For every $n$, the sequence $u$ is strictly log-concave on $\{0,\dots,n\}$, and for all $k$
\[
u_k<u_{k+1}\iff k+1<\lambda,\qquad u_k\le u_{k+1}\iff k+1\le\lambda .
\]
\end{theorem}

\begin{proof}
After clearing $\lambda^{2k+2}>0$, the Newton inequality is $((k+1)!)^2<k!\,(k+2)!$, i.e. $(k+1)^2<(k+2)(k+1)$, i.e. $k+1<k+2$. The criteria follow from $u_{k+1}/u_k=\lambda/(k+1)$.
\end{proof}

\begin{corollary}\label{cor:pois}
If $0<\lambda<n+1$ the Poisson weights form a threshold window on $\{0,\dots,n\}$ with threshold exactly $\lambda$; hence $\dminus=\lceil\lambda\rceil-1$, $\dplus=\lfloor\lambda\rfloor$, the maximiser set is $\{k:\lceil\lambda\rceil-1\le k\le\lfloor\lambda\rfloor\}$, and the top is a two-term plateau if and only if $\lambda\in\Z$.
\end{corollary}

\begin{lemma}\label{lem:poisscale}
Let $0<\lambda<n$ and $p=\lambda/n$, $q=1-\lambda/n$ (both positive, $p+q=1$). Then
\[
\theta(n,p,q)=(n+1)\frac{\lambda}{n}=\lambda+\frac{\lambda}{n}.
\]
\end{lemma}

\begin{theorem}[Cross-instance comparison]\label{thm:cross}
With $\lambda,p,q$ as in Lemma \ref{lem:poisscale},
\[
\dp_{\mathrm{Poisson}}(\lambda)\ \le\ \dp_{\mathrm{binomial}}(n,p,q)\ \le\ \dp_{\mathrm{Poisson}}(\lambda)+1 .
\]
\end{theorem}

\begin{proof}
Both are threshold windows on $\{0,\dots,n\}$, with thresholds $\lambda$ and $\lambda+\lambda/n$. Since $\lambda/n>0$, Theorem \ref{thm:mono} gives the left inequality; since $\lambda/n<1$, Theorem \ref{thm:step} gives the right one.
\end{proof}

The same argument applies to the lower brackets. A statement usually obtained by an approximation argument is here a comparison of two real numbers plus monotonicity of rounding, with an exact finite-$n$ error of at most one index.

\section{Algorithms}

\begin{algorithmx}[Mode location]
Given $n$ and $p,q>0$, compute $\theta=(n+1)p/(p+q)$ and return $(\lceil\theta\rceil-1,\ \lfloor\theta\rfloor)$ together with the boolean $\theta\in\Z$. Cost: $O(1)$ arithmetic operations, versus $\Theta(n)$ for evaluating and comparing all weights.
\end{algorithmx}

\begin{algorithmx}[Exact tie test]
For rational weights, integrality of $\theta$ is a divisibility question in $\Z$ and can be decided exactly; for integer weights $P,Q$ it is $(P+Q)\mid(n+1)P$. This avoids comparing a floating-point $\theta$ with its own rounding.
\end{algorithmx}

\begin{algorithmx}[Stable peak value]
Evaluate $\log w_k$ by accumulating $\log\frac{n-k}{k+1}+\log\frac pq$ from $\log w_0=n\log q$, at cost $O(\dplus)$, and validate against the bracket $[(p+q)^n/(n+1),\,(p+q)^n]$ of Theorem \ref{thm:peakbracket}.
\end{algorithmx}

\begin{algorithmx}[Vertex sweep]
For each $d\le n$ output $p=(2d+1)/(2n-2d+1)$, $q=1$, and verify $\lceil\theta\rceil-1=\lfloor\theta\rfloor=d$. Cost $O(1)$ per degree.
\end{algorithmx}

\section{Applications and discussion}

\textbf{Exact combinatorics.} The largest entry of row $n$ of Pascal's triangle is $\binom n{\lfloor n/2\rfloor}$, unique iff $n$ is even. For weighted rows $\binom nk P^kQ^{n-k}$, uniqueness is decided by $(P+Q)\nmid(n+1)P$. For example with $P=1,Q=2$ a tie occurs exactly when $3\mid n+1$; at $n=5$ the mode parameter is $2$ and indeed $\binom51 2^4=80=\binom52 2^3$.

\textbf{Estimates for sums.} Theorem \ref{thm:peakbracket} says the largest term carries at least a $1/(n+1)$ share of the total; with $p=q=1$ it yields $2^n/(n+1)\le\binom n{\lfloor n/2\rfloor}\le2^n$, the standard input to entropy and large-deviation arguments.

\textbf{Statistics.} For a binomial law with success probability $\pi=p/(p+q)$, the mode is $\lfloor(n+1)\pi\rfloor$, with a two-point mode exactly when $(n+1)\pi\in\Z$; the frequently quoted $n\pi$ can be off by one index. Likewise the Poisson mode is $\lfloor\lambda\rfloor$, with a tie iff $\lambda\in\Z$.

\textbf{Convex geometry.} Theorem \ref{thm:vertex} identifies the sweep of the maximiser under exponential tilting with the enumeration of the vertices of the upper convex hull of $\{(k,\log a_k)\}$: the finite shadow of the Legendre-duality picture behind exponential families.

\textbf{The role of strictness.} Positivity underwrites the ratio calculus; the strict Newton inequality is used exactly once, to exclude a three-term plateau. Under a weak Newton inequality the sequence remains unimodal but the maximiser interval may be arbitrarily long. Retaining \emph{both} the strict and the weak rise criteria in the definition of a threshold window is what makes the two bracketing degrees separately computable; a formalism recording only one cannot see the tie.

\section{Future directions}

\textbf{Quadratic criteria and the hypergeometric mode.} If the rise criterion reads $a_k<a_{k+1}\iff g(k)>0$ for a quadratic $g$ with a single sign change on $[0,n)$, one expects $\dminus=\lceil r\rceil-1$ and $\dplus=\lfloor r\rfloor$ for $r$ the unique root of $g$ in that range, with a tie iff $r\in\Z$. Nothing in the proofs of Theorems \ref{thm:explicit} and \ref{thm:gap} used linearity, only single crossing. Specialised to the hypergeometric weights $\binom mk\binom{N-m}{n-k}$ this predicts $\dplus=\lfloor(n+1)(m+1)/(N+2)\rfloor$.

\textbf{Plateau rigidity.} A tie means $\theta\in\Z$, an exact rational coincidence. One may conjecture that a strictly log-concave positive \emph{integer} sequence on $\{0,\dots,n\}$ with $\dplus=\dminus+1$ must have peak value at least $2^{\lfloor n/2\rfloor}$ divided by an explicit polynomial factor; contrapositively, small strictly log-concave integer sequences have unique maximisers. Exact ties force exact ratio relations near the peak, and strict log-concavity propagates quantitative bounds away from it.

\textbf{Higher-order brackets.} Explicit brackets for the second largest term, or for the level sets $\{k:a_k\ge\alpha\max_j a_j\}$, in terms of the same threshold data, would give effective width estimates for the bell curve without Stirling's formula.

\textbf{Several dimensions.} For multinomial weights $\binom n{k_1,\dots,k_r}\prod p_i^{k_i}$ one expects the maximiser to be trapped in a lattice cell determined by the real point with coordinates $(n+1)p_i/\sum_jp_j$, with ties governed by which coordinates are integral. The theory above is the case $r=2$, and the right multivariate analogue of ``the gap is at most one'' is the natural test of the framework.

\section{Summary}

For a strictly log-concave positive window: $\dminus\le\dplus\le\dminus+1$, with equality in the second place exactly at a two-term plateau, and the maximiser set is exactly $[\dminus,\dplus]$. For a threshold window: $\dminus=\lceil\theta\rceil-1$, $\dplus=\lfloor\theta\rfloor$, gap $1$ iff $\theta\in\Z$, both degrees monotone in $\theta$ and shifting by at most one under a sub-unit shift. For the binomial weights: $\theta=(n+1)p/(p+q)$, with the arithmetic tie criterion $(P+Q)\mid(n+1)P$ for integer weights and ``$n$ odd'' in the classical case; the peak value lies in $[(p+q)^n/(n+1),(p+q)^n]$; the mode is a monotone unit staircase in $n$; and every degree is the unique mode for a suitable weight. For the Poisson weights: $\theta=\lambda$, with the binomial mode under the scaling $p=\lambda/n$ exceeding the Poisson mode by $0$ or $1$.

